SELECT COUNT(*) FROM order_item oi
JOIN orders o ON o.id = oi.order_id
WHERE o.session_id = #{sessionId}
AND oi.id_card_no IN

    #{attendeeId}

AND o.status NOT IN (5, 7)

SELECT oi.category_id as categoryId, COUNT(*) AS cnt
FROM order_item oi
JOIN orders o ON o.id = oi.order_id
WHERE o.user_id = #{currentId}
AND o.session_id = #{sessionId}
AND oi.category_id IN

    #{categoryId}

AND o.status NOT IN (5, 7)
GROUP BY oi.category_id
